using namespace std;
void heapify(vector<int>&a,int i,int sz){
    int lg=i,l=2*i+1,r=2*i+2;
    if(l<sz&&a[l]>a[lg]) lg=l;
    if(r<sz&&a[r]>a[lg]) lg=r;
    if(lg!=i){swap(a[i],a[lg]);heapify(a,lg,sz);}
}
int main(){
    int n; cin>>n;
    vector<int> arr(n); for(int&x:arr) cin>>x;
    for(int i=n/2-1;i>=0;i--) heapify(arr,i,n);
    for(int i=n-1;i>0;i--){swap(arr[0],arr[i]);heapify(arr,0,i);}
    for(int i=0;i<n;i++){if(i) cout<<' ';cout<<arr[i];}
    cout<<'\n';
}

